const sheetRow = $('Loop Over Review Rows (1 by 1)').last().json || {};
const pgOut = $input.first().json || {};
const dbRow = pgOut.cached_resume || pgOut || {};
const activeRules = Array.isArray(pgOut.active_rules) ? pgOut.active_rules : [];

const notesForResume = String(sheetRow['Notes for Resume'] || '').trim();
const notesByReviewer = String(sheetRow['Notes by Reviewer'] || '').trim();
const genericNotes = String(sheetRow['Notes'] || '').trim();

const reviewerNotes = [notesForResume, notesByReviewer, genericNotes]
  .filter(n => n && n.toLowerCase() !== 'none provided')
  .join('\n');

// Detect if user wrote 'For this resume' (one-off edit that must NOT be learned globally)
const isForThisResumeOnly = /\b(for this resume|this resume only|only for this resume|just for this resume)\b/i.test(reviewerNotes);

const sNo = String(sheetRow['S. No.'] || dbRow.s_no || '');
const resumeId = String(dbRow.resume_id || sheetRow['Resume_id'] || `RES-${sNo || Date.now()}`);
const company = String(sheetRow['Company'] || dbRow.company_name || 'Company').trim();
const cleanCompany = company.replace(/[^a-zA-Z0-9_-]/g, '_').replace(/^_+|_+$/g, '') || 'Company';
const positionTitle = String(sheetRow['Position - Title'] || dbRow.position_title || 'Senior Data & Business Analyst').trim();
const jobDescription = String(sheetRow['Position - Description'] || '').trim();
const roleCategory = String(dbRow.role_category || 'bi_data_analyst');
const nextRevision = Number(dbRow.revision_count || 1) + 1;

const applicableRulesText = activeRules
  .filter(r => {
    const rc = String(r.role_category || 'ALL').toUpperCase();
    return rc === 'ALL' || rc === 'GLOBAL' || rc === roleCategory.toUpperCase();
  })
  .map((r, idx) => `${idx + 1}. [${r.section_name}]: ${r.rule_instruction}`)
  .join('\n') || '1. [skills]: All skill names and category names in the Core Skills section MUST be in Title Case.';

const hasCachedHtml = Boolean(dbRow.summary_html && String(dbRow.summary_html).trim().length > 10);

const fallbackSummaryHtml = `<p><strong>Senior Data &amp; Business Analyst</strong> with 5+ years of experience translating operational and financial workflows into scalable analytics, automated pipelines, and testable engineering requirements using <strong>SQL, Python, Tableau, and n8n</strong>.</p>`;
