const FALLBACK_MODELS = [
  'gemini-3.5-flash-lite',
  'gemini-2.5-flash-lite',
  'gemini-2.5-flash',
  'gemini-2.0-flash-lite',
  'gemini-2.0-flash',
  'gemini-1.5-flash',
  'gemma-2-27b-it'
];
const upstream = $('Merge Sheet Feedback & Cached HTML Sections').last().json;
const staticData = $getWorkflowStaticData('node');
const rowKey = String(upstream.sNo || upstream.resumeId || 'row');
if (staticData.lastRowKey !== rowKey) {
  staticData.lastRowKey = rowKey;
  staticData.failCount = 0;
}
staticData.failCount = (staticData.failCount || 0) + 1;
if (staticData.failCount > 14) {
  throw new Error(`All 7 fallback AI models overloaded at AI Router after ${staticData.failCount} switches.`);
}
const nextModel = FALLBACK_MODELS[staticData.failCount % FALLBACK_MODELS.length];
return [{ json: { ...upstream, _activeModel: nextModel, _failoverAttempt: staticData.failCount } }];

const ctx = $('Merge Sheet Feedback & Cached HTML Sections').last().json;
const rawText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleanJson = String(rawText).replace(/```json|```/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    sections_to_regenerate: ['summary', 'skills', 'experience'],
    primary_section_for_rule: 'global',
    specific_edit_instructions: ctx.reviewerNotes,
    rule_scope: ctx.isForThisResumeOnly ? 'NONE' : 'ALL',
    extracted_rule: ctx.isForThisResumeOnly ? '' : ctx.reviewerNotes
  };
}

const isOneOff = Boolean(
  ctx.isForThisResumeOnly ||
  String(parsed.rule_scope || '').toUpperCase() === 'NONE' ||
  /\b(for this resume|this resume only|only for this resume|just for this resume)\b/i.test(String(parsed.extracted_rule || ''))
);

const extractedRule = isOneOff ? '' : String(parsed.extracted_rule || '').trim();
const shouldSaveLearnedRule = !isOneOff && extractedRule.length > 5;

const targetRoleForRule = parsed.rule_scope === 'role_specific' ? ctx.roleCategory : 'ALL';
const primarySection = String(parsed.primary_section_for_rule || (parsed.sections_to_regenerate && parsed.sections_to_regenerate[0]) || 'global').toLowerCase();
const sectionsToRegenerate = !ctx.hasCachedHtml
  ? ['summary', 'skills', 'experience']
  : (Array.isArray(parsed.sections_to_regenerate) && parsed.sections_to_regenerate.length > 0 ? parsed.sections_to_regenerate : ['summary', 'experience']);

return [{
  json: {
    ...ctx,
    sectionsToRegenerate,
    primarySectionForRule: primarySection,
    specificEditInstructions: parsed.specific_edit_instructions || ctx.reviewerNotes,
    targetRoleForRule,
    extractedRule,
    shouldSaveLearnedRule,
    _activeModel: 'gemini-3.5-flash-lite'
  }
}];

