const FALLBACK_MODELS = [
  'gemini-3.5-flash-lite',
  'gemini-2.5-flash-lite',
  'gemini-2.5-flash',
  'gemini-2.0-flash-lite',
  'gemini-2.0-flash',
  'gemini-1.5-flash',
  'gemma-2-27b-it'
];
const upstream = $('Parse Router Decision & Learned Rule').last().json;
const staticData = $getWorkflowStaticData('node');
const rowKey = String(upstream.sNo || upstream.resumeId || 'row');
if (staticData.lastRowKey !== rowKey) {
  staticData.lastRowKey = rowKey;
  staticData.failCount = 0;
}
staticData.failCount = (staticData.failCount || 0) + 1;
if (staticData.failCount > 14) {
  throw new Error(`All 7 fallback AI models overloaded at Section Rewriter after ${staticData.failCount} switches.`);
}
const nextModel = FALLBACK_MODELS[staticData.failCount % FALLBACK_MODELS.length];
return [{ json: { ...upstream, _activeModel: nextModel, _failoverAttempt: staticData.failCount } }];

const ctx = $('Parse Router Decision & Learned Rule').last().json;
const rawText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleanJson = String(rawText).replace(/```json|```/gi, '').trim();
let updated = {};
try {
  updated = JSON.parse(cleanJson);
} catch (e) {
  updated = {};
}

const cleanHtml = (val, fallback) => {
  const s = String(val || '').replace(/```html|```/gi, '').trim();
  return s.length > 5 ? s : fallback;
};

const toTitleCaseSkillsHtml = (html) => {
  const acronyms = new Set(['SQL', 'ETL', 'BI', 'KPI', 'KPIS', 'UAT', 'CRM', 'API', 'AI', 'LLM', 'AWS', 'GCP', 'SOP', 'SLA', 'P&L', 'B2B', 'B2C', 'FP&A', 'HR', 'IT', 'QA', 'UI', 'UX', 'ROI', 'OKR', 'OKRS']);
  const minor = new Set(['and', 'or', 'of', 'in', 'to', 'for', 'with', 'on', 'at', 'by']);
  return String(html || '').replace(/(>[^<]+<)/g, (segment) => {
    return segment.replace(/\b([A-Za-z0-9&/+-]+)\b/g, (word, _, offset) => {
      if (word.toLowerCase() === 'n8n') return 'n8n';
      const upper = word.toUpperCase();
      if (acronyms.has(upper)) return upper;
      if (minor.has(word.toLowerCase()) && offset > 1) return word.toLowerCase();
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    });
  });
};

const flagged = new Set(ctx.sectionsToRegenerate || []);

const summaryHtml = flagged.has('summary') ? cleanHtml(updated.summary_html, ctx.summaryHtml) : ctx.summaryHtml;
const rawSkillsHtml = flagged.has('skills') ? cleanHtml(updated.skills_html, ctx.skillsHtml) : ctx.skillsHtml;
const skillsHtml = toTitleCaseSkillsHtml(rawSkillsHtml);
const experienceHtml = flagged.has('experience') ? cleanHtml(updated.experience_html, ctx.experienceHtml) : ctx.experienceHtml;
const certificationsHtml = flagged.has('certifications') ? cleanHtml(updated.certifications_html, ctx.certificationsHtml) : ctx.certificationsHtml;
const hobbiesHtml = flagged.has('hobbies') ? cleanHtml(updated.hobbies_html, ctx.hobbiesHtml) : ctx.hobbiesHtml;
const educationHtml = ctx.educationHtml;
const marketingProjectsHtml = ctx.marketingProjectsHtml || '';

const customCss = `
