`;

const fullHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Sumanto_Banerjee-Resume-${ctx.cleanCompany}_v${ctx.nextRevision}</title>
  <style>${customCss}</style>
</head>
<body>
