  ${hobbiesHtml}
</body>
</html>`;

const pdfFileName = `Sumanto_Banerjee-Resume-${ctx.cleanCompany}_v${ctx.nextRevision}.pdf`;

return [{
  json: {
    ...ctx,
    summaryHtml,
    skillsHtml,
    experienceHtml,
    certificationsHtml,
    educationHtml,
    hobbiesHtml,
